"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["6202"],{587(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>h,frontMatter:()=>l,contentTitle:()=>o,toc:()=>c,assets:()=>r});var t=JSON.parse('{"id":"networks/etherchannel","title":"EtherChannel & Link Aggregation","description":"Link aggregation bundles multiple physical links between two devices into a single logical link \u2014 increasing total bandwidth and providing redundancy, while presenting Spanning Tree with just one logical link instead of multiple parallel physical ones (avoiding the loop-and-blocking tradeoff entirely for that bundle).","source":"@site/docs/networks/15-etherchannel.md","sourceDirName":"networks","slug":"/networks/etherchannel","permalink":"/Mindstack/docs/networks/etherchannel","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":15,"frontMatter":{"title":"EtherChannel & Link Aggregation","sidebar_label":"EtherChannel","sidebar_position":15},"sidebar":"networkSidebar","previous":{"title":"Spanning Tree (STP)","permalink":"/Mindstack/docs/networks/stp"},"next":{"title":"Switch Security","permalink":"/Mindstack/docs/networks/switch-security"}}'),a=i(4848),s=i(8453);let l={title:"EtherChannel & Link Aggregation",sidebar_label:"EtherChannel",sidebar_position:15},o="EtherChannel & Link Aggregation",r={},c=[{value:"Why Bundle Links?",id:"why-bundle-links",level:2},{value:"Link Aggregation Protocols",id:"link-aggregation-protocols",level:2},{value:"Load Balancing Across Bundled Links",id:"load-balancing-across-bundled-links",level:2},{value:"Configuration Example (Cisco IOS)",id:"configuration-example-cisco-ios",level:2},{value:"Requirements for Successful Bundling",id:"requirements-for-successful-bundling",level:2},{value:"Multi-Chassis Link Aggregation",id:"multi-chassis-link-aggregation",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"etherchannel--link-aggregation",children:"EtherChannel & Link Aggregation"})}),"\n",(0,a.jsx)(n.p,{children:"Link aggregation bundles multiple physical links between two devices into a single logical link \u2014 increasing total bandwidth and providing redundancy, while presenting Spanning Tree with just one logical link instead of multiple parallel physical ones (avoiding the loop-and-blocking tradeoff entirely for that bundle)."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"why-bundle-links",children:"Why Bundle Links?"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'Without aggregation:                With aggregation (EtherChannel):\n[Switch A]\u2550\u2550[Switch B]               [Switch A]\u2550\u2550\u2550[Switch B]\n[Switch A]\u2550\u2550[Switch B]  (2nd link)   (logically ONE 2Gbps link,\n                                       physically TWO 1Gbps cables)\n\nWithout bundling, STP sees two parallel physical links between the\nsame two switches as a LOOP RISK and blocks one of them entirely\n(see Spanning Tree Protocol) \u2014 wasting half the available bandwidth\nand capacity that was paid for.\n\nWith EtherChannel, STP sees ONE logical interface (a "Port Channel")\nand treats the bundle as if it were a single link \u2014 both physical\nlinks are actively used, traffic is load-balanced across them, and\nif one physical link fails, traffic simply continues over the\nremaining link(s) with no STP recalculation needed.\n'})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"link-aggregation-protocols",children:"Link Aggregation Protocols"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'Static (manual) \u2014 both ends are simply configured to treat the links\n  as a bundle, with no negotiation protocol \u2014 works, but risky: if one\n  side is misconfigured (e.g. fewer/more links, or "static" while the\n  other side expects negotiation), you can end up with a silent\n  mismatch, sometimes resulting in an actual unprotected forwarding\n  loop. Generally considered less safe than a negotiated protocol.\n\nPAgP (Port Aggregation Protocol) \u2014 Cisco proprietary, predates the\n  open standard, negotiates and verifies that bundled links are\n  correctly matched on both ends before activating the bundle.\n\nLACP (Link Aggregation Control Protocol) \u2014 IEEE 802.3ad (and now part\n  of 802.1AX) open standard, functionally similar to PAgP but vendor-\n  neutral, making it the standard choice for any modern multi-vendor\n  or future-proofed deployment.\n'})}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"LACP/PAgP negotiation modes:\n  Active / Desirable \u2014 actively sends negotiation packets, initiates\n                        bundle formation\n  Passive / Auto     \u2014 waits to receive negotiation packets, responds\n                        but doesn't initiate\n\nBoth ends must NOT both be set to passive/auto \u2014 if neither side\ninitiates, the bundle never forms. At least one side must be active\n(LACP) or desirable (PAgP).\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"load-balancing-across-bundled-links",children:"Load Balancing Across Bundled Links"}),"\n",(0,a.jsxs)(n.p,{children:["A common misconception: EtherChannel does NOT simply alternate packets round-robin across the bundled links. Instead, it uses a ",(0,a.jsx)(n.strong,{children:"hashing algorithm"})," based on configurable fields (source/destination MAC, source/destination IP, or port numbers, or a combination) to deterministically assign each individual conversation (flow) to one specific physical link in the bundle."]}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"Why hash instead of round-robin? To PRESERVE PACKET ORDER within a\nsingle conversation. If packets from the same TCP flow could land on\ndifferent physical links with different latencies, they might arrive\nout of order, forcing the receiving TCP stack to do unnecessary\nreordering work (and potentially mistaking it for packet loss,\ntriggering unnecessary retransmission \u2014 see TCP Fundamentals).\nHashing the SAME flow consistently to the SAME physical link avoids\nthis entirely, at the cost of not perfectly balancing load packet-by-\npacket (a single very high-bandwidth flow will always use only ONE\nphysical link's worth of bandwidth, never spreading across multiple).\n\nCommon hash inputs (configurable, varies by platform):\n  src-mac, dst-mac\n  src-ip, dst-ip\n  src-port, dst-port (Layer 4, more granular \u2014 better balancing when\n                       many flows exist between the same two IP hosts)\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"configuration-example-cisco-ios",children:"Configuration Example (Cisco IOS)"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"! Configure LACP EtherChannel between two switches (2 links)\nSwitch(config)# interface range gigabitethernet 0/23-24\nSwitch(config-if-range)# channel-group 1 mode active\nSwitch(config-if-range)# exit\n\n! The resulting logical interface\nSwitch(config)# interface port-channel 1\nSwitch(config-if)# switchport mode trunk\nSwitch(config-if)# switchport trunk allowed vlan 10,20,30\n\n! Configure the load-balancing hash method (platform-dependent options)\nSwitch(config)# port-channel load-balance src-dst-ip\n\n! Verification\nSwitch# show etherchannel summary\nSwitch# show etherchannel load-balance\nSwitch# show interfaces port-channel 1\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"requirements-for-successful-bundling",children:"Requirements for Successful Bundling"}),"\n",(0,a.jsx)(n.p,{children:"All physical links in a bundle must match on several characteristics, or the bundle will fail to form (or individual links will be excluded):"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"\u2713 Same speed (e.g. all 1 Gbps, or all 10 Gbps \u2014 not a mix)\n\u2713 Same duplex (all full-duplex)\n\u2713 Same VLAN/trunk configuration (all access in the same VLAN, or all\n  trunks with matching allowed VLAN lists and native VLAN)\n\u2713 Same switchport mode (all access, or all trunk \u2014 not mixed)\n\u2713 Same negotiation mode compatibility (active+active/passive, or\n  desirable+desirable/auto \u2014 not active+passive incompatibilities\n  for LACP specifically, though active+passive DOES work; passive+\n  passive does NOT)\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"multi-chassis-link-aggregation",children:"Multi-Chassis Link Aggregation"}),"\n",(0,a.jsxs)(n.p,{children:["A more advanced variant bundles links not just across multiple physical cables, but across links terminating on ",(0,a.jsx)(n.strong,{children:"two different physical switches"}),", providing redundancy even against the failure of an entire switch chassis, not just a single link."]}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"[Server]\u2550\u2550\u2557\n          \u2560\u2550\u2550[Switch A]\n          \u255A\u2550\u2550[Switch B]   (Switch A and B act as ONE logical\n                            switch for EtherChannel purposes)\n\nThis requires vendor-specific technology to make two physical switches\nappear as a single logical switch to the connected device for\naggregation purposes:\n  Cisco \u2014 Virtual Port Channel (vPC) on Nexus platforms, or\n          StackWise/StackWise Virtual on Catalyst platforms\n  Other vendors \u2014 similar concepts under different names (MLAG being\n          a common generic industry term \u2014 Multi-Chassis Link Aggregation)\n"})}),"\n",(0,a.jsx)(n.p,{children:"This pattern is extremely common in modern datacenter and server-facing top-of-rack switch designs, where a server (or another switch) connects redundantly to two separate physical switches for maximum resilience, while still appearing as one simple aggregated link from the server's perspective."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Always use LACP (active mode on at least one side) over static/manual bundling in production \u2014 the negotiation protects against silent misconfiguration that could otherwise create an unprotected loop or a non-functional bundle."}),"\n",(0,a.jsx)(n.li,{children:'When experiencing a "this one specific large file transfer is slow but overall switch throughput looks fine," remember that a single flow on an EtherChannel bundle is hashed to exactly ONE physical link \u2014 it will never exceed that single link\'s bandwidth, even if the bundle has multiple links and plenty of spare aggregate capacity.'}),"\n",(0,a.jsxs)(n.li,{children:["Mismatched configuration (speed, duplex, VLAN, trunk settings) across bundled links is the most common real-world cause of EtherChannel bundles failing to form or operating in a degraded state \u2014 always double check ",(0,a.jsx)(n.code,{children:"show etherchannel summary"}),' for any link shown as individually "suspended" rather than part of the active bundle.']}),"\n"]}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"EtherChannel/link aggregation bundles multiple physical links into one logical link, increasing usable bandwidth and avoiding STP blocking one of the redundant physical links."}),"\n",(0,a.jsx)(n.li,{children:"LACP (open IEEE standard) is preferred over PAgP (Cisco proprietary) or static/manual bundling for safety via negotiation."}),"\n",(0,a.jsx)(n.li,{children:"Traffic is load-balanced via a hashing algorithm (based on MAC/IP/port fields) that keeps each individual flow consistently on one physical link to preserve packet ordering \u2014 meaning a single flow never exceeds one physical link's bandwidth even within a larger bundle."}),"\n",(0,a.jsx)(n.li,{children:"All bundled links must match in speed, duplex, and VLAN/trunk configuration or the bundle will fail to form correctly."}),"\n",(0,a.jsx)(n.li,{children:"Multi-chassis link aggregation (vPC, StackWise Virtual, MLAG) extends this concept across two physical switches, protecting against a full switch chassis failure, not just a single link failure."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>l,x:()=>o});var t=i(6540);let a={},s=t.createContext(a);function l(e){let n=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:l(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);